import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CBxkvBm_.js";const h=JSON.parse('{"title":"OWL2 Ontology (.owl, .owl2, .ofn, .ttl)","description":"","frontmatter":{},"headers":[],"relativePath":"languages/owl2.md","filePath":"languages/owl2.md"}'),i={name:"languages/owl2.md"};function l(n,e,d,r,c,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="owl2-ontology-owl-owl2-ofn-ttl" tabindex="-1">OWL2 Ontology (<code>.owl</code>, <code>.owl2</code>, <code>.ofn</code>, <code>.ttl</code>) <a class="header-anchor" href="#owl2-ontology-owl-owl2-ofn-ttl" aria-label="Permalink to &quot;OWL2 Ontology (`.owl`, `.owl2`, `.ofn`, `.ttl`)&quot;">​</a></h1><p><code>@modelscript/owl2</code> (<code>languages/owl2</code>) brings formal ontological engineering, Description Logic ($\\mathcal{SROIQ}(\\mathcal{D})$) reasoning, and SPARQL / Leapfrog Triejoin graph querying directly into the ModelScript compiler.</p><hr><h2 id="supported-extensions-formats" tabindex="-1">Supported Extensions &amp; Formats <a class="header-anchor" href="#supported-extensions-formats" aria-label="Permalink to &quot;Supported Extensions &amp; Formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Extension</th><th style="text-align:left;">Format</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.owl</code>, <code>.owl2</code>, <code>.ofn</code></td><td style="text-align:left;">W3C OWL 2 Functional-Style Syntax (<code>Prefix(...)</code>, <code>Ontology(...)</code>)</td></tr><tr><td style="text-align:left;"><code>.ttl</code></td><td style="text-align:left;">RDF Turtle / Ontological Triple Assertions</td></tr></tbody></table><hr><h2 id="owl-2-dl-axiom-class-expression-lowering" tabindex="-1">OWL 2 DL Axiom &amp; Class Expression Lowering <a class="header-anchor" href="#owl-2-dl-axiom-class-expression-lowering" aria-label="Permalink to &quot;OWL 2 DL Axiom &amp; Class Expression Lowering&quot;">​</a></h2><p><code>lowerCstToAxioms(tree, sourceText)</code> (<code>languages/owl2/src/cst-lowering.ts</code>) lowers the linear-memory CST into an arena-backed <code>OntologyStore</code> supporting over 35 OWL 2 DL axiom and class expression constructs:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Category</th><th style="text-align:left;">Supported OWL 2 Functional-Style Constructs</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Declarations</strong></td><td style="text-align:left;"><code>Declaration(Class(...))</code>, <code>Declaration(ObjectProperty(...))</code>, <code>Declaration(DataProperty(...))</code>, <code>Declaration(NamedIndividual(...))</code></td></tr><tr><td style="text-align:left;"><strong>Class Axioms</strong></td><td style="text-align:left;"><code>SubClassOf</code>, <code>EquivalentClasses</code>, <code>DisjointClasses</code></td></tr><tr><td style="text-align:left;"><strong>Boolean &amp; Nominal Class Expressions</strong></td><td style="text-align:left;"><code>ObjectIntersectionOf</code>, <code>ObjectUnionOf</code>, <code>ObjectComplementOf</code>, <code>ObjectOneOf</code></td></tr><tr><td style="text-align:left;"><strong>Object Property Restrictions</strong></td><td style="text-align:left;"><code>ObjectSomeValuesFrom</code>, <code>ObjectAllValuesFrom</code>, <code>ObjectHasSelf</code>, <code>ObjectHasValue</code>, <code>ObjectMinCardinality</code>, <code>ObjectMaxCardinality</code>, <code>ObjectExactCardinality</code></td></tr><tr><td style="text-align:left;"><strong>Data Property Restrictions</strong></td><td style="text-align:left;"><code>DataSomeValuesFrom</code>, <code>DataAllValuesFrom</code>, <code>DataMinCardinality</code>, <code>DataMaxCardinality</code>, <code>DataExactCardinality</code></td></tr><tr><td style="text-align:left;"><strong>Property Hierarchy &amp; Inversion</strong></td><td style="text-align:left;"><code>SubObjectPropertyOf</code>, <code>SubDataPropertyOf</code>, <code>InverseObjectProperties</code>, <code>DisjointObjectProperties</code></td></tr><tr><td style="text-align:left;"><strong>Property Domains &amp; Ranges</strong></td><td style="text-align:left;"><code>ObjectPropertyDomain</code>, <code>ObjectPropertyRange</code>, <code>DataPropertyDomain</code>, <code>DataPropertyRange</code></td></tr><tr><td style="text-align:left;"><strong>Property Characteristics</strong></td><td style="text-align:left;"><code>FunctionalObjectProperty</code>, <code>InverseFunctionalObjectProperty</code>, <code>ReflexiveObjectProperty</code>, <code>IrreflexiveObjectProperty</code>, <code>SymmetricObjectProperty</code>, <code>AsymmetricObjectProperty</code>, <code>TransitiveObjectProperty</code>, <code>FunctionalDataProperty</code></td></tr><tr><td style="text-align:left;"><strong>ABox Individual Assertions</strong></td><td style="text-align:left;"><code>ClassAssertion</code>, <code>ObjectPropertyAssertion</code>, <code>DataPropertyAssertion</code>, <code>NegativeObjectPropertyAssertion</code>, <code>NegativeDataPropertyAssertion</code>, <code>SameIndividual</code>, <code>DifferentIndividuals</code></td></tr></tbody></table><div class="language-lisp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lisp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Prefix(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:=&lt;http://example.org/spacecraft#&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ontology(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&lt;http</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">://example.org/spacecraft&gt;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  Declaration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:Thruster</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  Declaration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:Actuator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  Declaration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ObjectProperty(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:mountedOn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  Declaration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(DataProperty(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:nominalThrustN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  SubClassOf(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:Thruster</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :Actuator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  SubClassOf(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:Thruster</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ObjectSomeValuesFrom(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:mountedOn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :ReactionControlPod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ClassAssertion(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:Thruster</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :RCS_Thruster_A1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  DataPropertyAssertion(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:nominalThrustN</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :RCS_Thruster_A1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;22.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">^^xsd:double)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><hr><h2 id="description-logic-tableau-reasoner-leapfrog-triejoin" tabindex="-1">Description Logic Tableau Reasoner &amp; Leapfrog Triejoin <a class="header-anchor" href="#description-logic-tableau-reasoner-leapfrog-triejoin" aria-label="Permalink to &quot;Description Logic Tableau Reasoner &amp; Leapfrog Triejoin&quot;">​</a></h2><p><code>@modelscript/owl2</code> includes an in-memory <strong>$\\mathcal{SROIQ}(\\mathcal{D})$ Tableau Reasoner</strong> (<code>TableauReasoner</code> in <code>languages/owl2/src/reasoner/</code>) and a worst-case optimal <strong>Leapfrog Triejoin</strong> engine (<code>executeBGP</code> in <code>languages/owl2/src/query/leapfrog.ts</code>):</p><ol><li><strong>Consistency &amp; Satisfiability Checking</strong>: Detects unsatisfiable classes (<code>DisjointClasses</code> violations, cardinality contradictions, irreflexive/asymmetric cycles, negative property assertion conflicts) and surfaces exact source diagnostics (<code>OWL2001</code>–<code>OWL2005</code>).</li><li><strong>Justification &amp; Explanation Tracing</strong>: Computes minimal unsatisfiability justifications (<code>explain_inference</code>) explaining why a class or individual violates ontology axioms.</li><li><strong>SPARQL &amp; Multi-Way BGP Joins</strong>: Evaluates conjunctive Basic Graph Patterns (BGPs) in $O(\\text{AGM bound})$ worst-case optimal time without materializing intermediate Cartesian products.</li></ol><hr><h2 id="interactive-2d-ontology-diagram-bidirectional-writeback" tabindex="-1">Interactive 2D Ontology Diagram &amp; Bidirectional Writeback <a class="header-anchor" href="#interactive-2d-ontology-diagram-bidirectional-writeback" aria-label="Permalink to &quot;Interactive 2D Ontology Diagram &amp; Bidirectional Writeback&quot;">​</a></h2><p><code>languages/owl2/src/diagram/</code> provides an interactive 2D graph visualization and editing surface for OWL 2 ontologies:</p><ul><li><strong>Visual Graph Projection</strong>: Renders <code>Class</code> nodes, <code>NamedIndividual</code> instances, <code>SubClassOf</code> inheritance hierarchies, and <code>ObjectPropertyDomain</code>/<code>ObjectPropertyRange</code> directed edges.</li><li><strong>Bidirectional CST Writeback (<code>owl2Language.writeback</code>)</strong>: Adding/deleting nodes or edges in the diagram (<code>add_node</code>, <code>delete_node</code>, <code>add_edge</code>, <code>delete_edge</code>, <code>rename_node</code>, <code>update_parameter</code>) patches the Functional-Style <code>.owl</code> source text directly—inserting or removing <code>Declaration(...)</code>, <code>SubClassOf(...)</code>, or <code>DataPropertyAssertion(...)</code> axioms in place.</li></ul><hr><h2 id="dedicated-owl2-mcp-server-tools" tabindex="-1">Dedicated <code>owl2-mcp</code> Server Tools <a class="header-anchor" href="#dedicated-owl2-mcp-server-tools" aria-label="Permalink to &quot;Dedicated `owl2-mcp` Server Tools&quot;">​</a></h2><p>The <code>@modelscript/owl2</code> MCP server (<code>languages/owl2/src/mcp/server.ts</code>) exposes five specialized tools to AI agents:</p><table tabindex="0"><thead><tr><th style="text-align:left;">MCP Tool</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>validate_system_consistency</code></td><td style="text-align:left;">Parses an OWL 2 Functional Syntax ontology, runs the $\\mathcal{SROIQ}$ Tableau Reasoner, and returns consistency status, unsatisfiable classes, and inferred <code>SubClassOf</code> hierarchy</td></tr><tr><td style="text-align:left;"><code>query_ontology_sparql</code></td><td style="text-align:left;">Executes a SPARQL <code>SELECT</code> <code>WHERE</code> query over the ontology&#39;s inferred RDF triple graph</td></tr><tr><td style="text-align:left;"><code>query_ontology_bgp</code></td><td style="text-align:left;">Evaluates a conjunctive Basic Graph Pattern (BGP) using the worst-case optimal Leapfrog Triejoin algorithm</td></tr><tr><td style="text-align:left;"><code>explain_inference</code></td><td style="text-align:left;">Computes formal axiomatic justifications explaining why an entailment holds or why a class is unsatisfiable</td></tr><tr><td style="text-align:left;"><code>trace_fault_propagation</code></td><td style="text-align:left;">Traces transitive fault propagation (<code>TransitiveObjectProperty</code> / causal links) from a starting component individual across the system topology</td></tr></tbody></table><hr><h2 id="polyglot-tgg-rules" tabindex="-1">Polyglot TGG Rules <a class="header-anchor" href="#polyglot-tgg-rules" aria-label="Permalink to &quot;Polyglot TGG Rules&quot;">​</a></h2><p><code>@modelscript/owl2</code> defines 5 bidirectional Triple Graph Grammar (TGG) rules in <code>languages/owl2/src/language.ts</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Rule Name</th><th style="text-align:left;">Source (<code>owl2</code>)</th><th style="text-align:left;">Target Language</th><th style="text-align:left;">Target Construct</th></tr></thead><tbody><tr><td style="text-align:left;"><code>OWL2ClassToSysML2Part</code></td><td style="text-align:left;"><code>Declaration</code> (<code>Class</code>)</td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>PartDef</code></td></tr><tr><td style="text-align:left;"><code>OWL2SubClassToSysML2Specialization</code></td><td style="text-align:left;"><code>SubClassOf</code></td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>Specialization</code> (<code>:&gt;</code>)</td></tr><tr><td style="text-align:left;"><code>OWL2ObjectPropertyToSysML2Port</code></td><td style="text-align:left;"><code>Declaration</code> (<code>ObjectProperty</code>)</td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>PortUsage</code></td></tr><tr><td style="text-align:left;"><code>OWL2DataPropertyToSysML2Attribute</code></td><td style="text-align:left;"><code>Declaration</code> (<code>DataProperty</code>)</td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>AttributeUsage</code></td></tr><tr><td style="text-align:left;"><code>OWL2ClassToModelicaModel</code></td><td style="text-align:left;"><code>Declaration</code> (<code>Class</code>)</td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ClassDefinition</code> (<code>model</code>)</td></tr></tbody></table>',26)])])}const y=t(i,[["render",l]]);export{h as __pageData,y as default};
